function apiOrigin() {
  return (process.env.ALPHALAB_API_ORIGIN || 'http://127.0.0.1:8000').replace(/\/+$/, '')
}

async function run(input) {
  const artifactId = String(input.artifact_id || '').trim()
  const path = artifactId ? '/api/reports/' + encodeURIComponent(artifactId) : '/api/reports?limit=' + Math.max(1, Math.min(100, Number(input.limit || 20)))
  const response = await fetch(apiOrigin() + path, { headers: { Accept: 'application/json' } })
  if (!response.ok) throw new Error('AlphaLab API ' + response.status + ': ' + await response.text())
  return response.json()
}
